// PreToolUse-Hook: blockiert Edit und Write auf die Datei .env (Exit-Code 2)
let d = "";
process.stdin.on("data", c => d += c).on("end", () => {
  const p = (JSON.parse(d).tool_input || {}).file_path || "";
  if (/(^|[\\/])\.env$/.test(p)) {
    console.error("Blockiert vom Hook: .env ist geschuetzt.");
    process.exit(2);
  }
  process.exit(0);
});
